/**
 * The Content endpoints, as `notra.content`.
 */
export class ContentResource {
  readonly #transport: Transport;

  constructor(transport: Transport) {
    this.#transport = transport;
  }

  /**
   * List posts
   *
   * Returns posts for the organization the API key belongs to, newest first by default. Only published posts are included unless you pass status=draft,published. Blog posts and changelogs include a metadata object with cover image, tags, excerpt, authors, featured, noindex, hidden and displayDate; it is null for other content types.
   *
   * `GET /v1/posts`
   */
  listPosts(params?: ListPostsParams, options?: RequestOptions): Promise<ListPostsResult> {
    return this.#transport.call(OPERATIONS.listPosts, params, options) as Promise<ListPostsResult>;
  }

  /**
   * Create a post
   *
   * Creates a post directly without generation. Omit markdown to create an empty draft you fill in later through the dashboard or PATCH /v1/posts/{postId}. Slugs are only accepted for blog posts and changelogs.
   *
   * `POST /v1/posts`
   */
  createPost(params: CreatePostParams, options?: RequestOptions): Promise<CreatePostResult> {
    return this.#transport.call(OPERATIONS.createPost, params, options) as Promise<CreatePostResult>;
  }

  /**
   * List post authors
   *
   * Returns the organization's authors, sorted by name. Authors are created in the dashboard; pass their IDs in metadata.authorIds when updating a blog post or changelog. Blog posts on a Notra Sites site can also use that site's own authors from GET /v1/sites/{siteId}/authors.
   *
   * `GET /v1/posts/authors`
   */
  listPostAuthors(options?: RequestOptions): Promise<ListPostAuthorsResult> {
    return this.#transport.call(OPERATIONS.listPostAuthors, undefined, options) as Promise<ListPostAuthorsResult>;
  }

  /**
   * Get a single post
   *
   * Returns the post. When no post with this ID exists in your organization, the response is still 200 with post set to null. Blog posts and changelogs include a metadata object with cover image, tags, excerpt, authors, featured, noindex, hidden and displayDate; it is null for other content types.
   *
   * `GET /v1/posts/{postId}`
   */
  getPost(params: GetPostParams, options?: RequestOptions): Promise<GetPostResult> {
    return this.#transport.call(OPERATIONS.getPost, params, options) as Promise<GetPostResult>;
  }

  /**
   * Update a single post
   *
   * Updates any combination of title, slug, markdown, status, and metadata. Sending markdown re-renders the stored HTML, and when title is omitted it is taken from the first heading in the markdown, keeping the existing title when the markdown has no heading. Slugs and metadata are only accepted for blog posts and changelogs. Inside metadata, send only the fields you want to change; tags and authorIds replace the stored list, and authorIds must come from GET /v1/posts/authors. A blog post that publishes to a Notra Sites site can also credit that site's authors as site:<id>, the ref from GET /v1/sites/{siteId}/authors. Title, slug, markdown, or metadata updates also sync a post linked to GitHub: an open pull request gets a new commit, and a repository set to publish directly gets a direct commit when its live branch allows one (unprotected, file unchanged on GitHub). Otherwise, including closed or merged pull requests, GitHub is left as is and no new pull request is opened; the post is still saved. GitHub sync errors occur after saving the post: 429 includes Retry-After, 502 indicates a sync error, and 504 indicates an unknown sync outcome. Check the PR before retrying an unconfirmed sync.
   *
   * `PATCH /v1/posts/{postId}`
   */
  updatePost(params: UpdatePostParams, options?: RequestOptions): Promise<UpdatePostResult> {
    return this.#transport.call(OPERATIONS.updatePost, params, options) as Promise<UpdatePostResult>;
  }

  /**
   * Delete a single post
   *
   * `DELETE /v1/posts/{postId}`
   */
  deletePost(params: DeletePostParams, options?: RequestOptions): Promise<DeletePostResult> {
    return this.#transport.call(OPERATIONS.deletePost, params, options) as Promise<DeletePostResult>;
  }

  /**
   * Queue async post generation
   *
   * Queues a generation job for one content type and returns 202 with the job. Select sources with integrations.github, integrations.linear, or github.repositories; when no selector is given at all, every connected GitHub integration is used. Pass pullRequest to write about one pull request, and brief to say what the post should cover. Requests with every dataPoints flag false, or with no usable source, are rejected with 400 and code NO_ACTIVITY_TYPES_SELECTED or NO_AVAILABLE_SOURCES before a job is created. Poll GET /v1/posts/generate/{jobId} until job.status is completed, failed, or skipped. Subscribe to post.generation.completed, post.generation.failed, or post.generation.skipped using /v1/webhooks for completion notifications.
   *
   * `POST /v1/posts/generate`
   */
  createPostGeneration(params: CreatePostGenerationParams, options?: RequestOptions): Promise<CreatePostGenerationResult> {
    return this.#transport.call(OPERATIONS.createPostGeneration, params, options) as Promise<CreatePostGenerationResult>;
  }

  /**
   * Open a draft pull request for a post
   *
   * Exports a saved blog post or changelog to a draft GitHub pull request, using the repository's configured content path, site metadata and image handling, the same as the dashboard. Always opens a pull request, even for repositories set to publish directly, and never merges it. Calling it again for the same post and repository updates its open pull request instead of opening another.
   *
   * `POST /v1/posts/{postId}/pull-request`
   */
  createPostPullRequest(params: CreatePostPullRequestParams, options?: RequestOptions): Promise<CreatePostPullRequestResult> {
    return this.#transport.call(OPERATIONS.createPostPullRequest, params, options) as Promise<CreatePostPullRequestResult>;
  }

  /**
   * Get async post generation status
   *
   * Returns the job and its event log. job.status moves from queued to running and ends as completed, failed, or skipped. job.postId is set once the post has been created; fetch it with GET /v1/posts/{postId}.
   *
   * `GET /v1/posts/generate/{jobId}`
   */
  getPostGeneration(params: GetPostGenerationParams, options?: RequestOptions): Promise<GetPostGenerationResult> {
    return this.#transport.call(OPERATIONS.getPostGeneration, params, options) as Promise<GetPostGenerationResult>;
  }

  /**
   * Get a post's publishing schedule
   *
   * Returns the post's current schedule with the state of every destination, or null when nothing is scheduled.
   *
   * `GET /v1/posts/{postId}/schedule`
   */
  getPostSchedule(params: GetPostScheduleParams, options?: RequestOptions): Promise<GetPostScheduleResult> {
    return this.#transport.call(OPERATIONS.getPostSchedule, params, options) as Promise<GetPostScheduleResult>;
  }

  /**
   * Schedule a post for publishing
   *
   * Publishes the post automatically at scheduledAt: it is marked as published in Notra and, optionally, opened and merged as a GitHub pull request or posted to a connected X or LinkedIn account. Replaces any schedule that has not started. The post is published as saved at that time, so later edits are included. Publishing runs within about a minute of scheduledAt; transient errors are retried automatically.
   *
   * `POST /v1/posts/{postId}/schedule`
   */
  schedulePost(params: SchedulePostParams, options?: RequestOptions): Promise<SchedulePostResult> {
    return this.#transport.call(OPERATIONS.schedulePost, params, options) as Promise<SchedulePostResult>;
  }

  /**
   * Cancel a post's publishing schedule
   *
   * Cancels every destination that has not started and clears failed ones. A destination that is already publishing cannot be interrupted: it finishes if it succeeds and ends canceled instead of being retried. inProgress reports it.
   *
   * `DELETE /v1/posts/{postId}/schedule`
   */
  cancelPostSchedule(params: CancelPostScheduleParams, options?: RequestOptions): Promise<CancelPostScheduleResult> {
    return this.#transport.call(OPERATIONS.cancelPostSchedule, params, options) as Promise<CancelPostScheduleResult>;
  }

  /**
   * Get a post's agent reach
   *
   * Returns AI crawler, citation and referral visits to the post's live page on its Notra Site, including its Markdown copy. Defaults to the last 30 days. agentReach is null when the post isn't live on a Site.
   *
   * `GET /v1/posts/{postId}/agent-reach`
   */
  getPostAgentReach(params: GetPostAgentReachParams, options?: RequestOptions): Promise<GetPostAgentReachResult> {
    return this.#transport.call(OPERATIONS.getPostAgentReach, params, options) as Promise<GetPostAgentReachResult>;
  }

  /**
   * List available brand identities
   *
   * Returns every brand identity in the organization, default identity first.
   *
   * `GET /v1/brand-identities`
   */
  listBrandIdentities(options?: RequestOptions): Promise<ListBrandIdentitiesResult> {
    return this.#transport.call(OPERATIONS.listBrandIdentities, undefined, options) as Promise<ListBrandIdentitiesResult>;
  }

  /**
   * Queue async brand identity generation
   *
   * Creates the brand identity immediately, then queues a website analysis that fills in company details, tone, and audience. The first brand identity in an organization becomes the default. Poll GET /v1/brand-identities/generate/{jobId} until job.status is completed or failed.
   *
   * `POST /v1/brand-identities/generate`
   */
  createBrandIdentity(params: CreateBrandIdentityParams, options?: RequestOptions): Promise<CreateBrandIdentityResult> {
    return this.#transport.call(OPERATIONS.createBrandIdentity, params, options) as Promise<CreateBrandIdentityResult>;
  }

  /**
   * Get async brand identity generation status
   *
   * Returns the analysis job. job.status moves from queued to running and ends as completed or failed; job.step shows the current stage while running. Fetch the finished identity with GET /v1/brand-identities/{brandIdentityId}.
   *
   * `GET /v1/brand-identities/generate/{jobId}`
   */
  getBrandIdentityGeneration(params: GetBrandIdentityGenerationParams, options?: RequestOptions): Promise<GetBrandIdentityGenerationResult> {
    return this.#transport.call(OPERATIONS.getBrandIdentityGeneration, params, options) as Promise<GetBrandIdentityGenerationResult>;
  }

  /**
   * Get a single brand identity
   *
   * Returns the brand identity. When no brand identity with this ID exists in your organization, the response is still 200 with brandIdentity set to null.
   *
   * `GET /v1/brand-identities/{brandIdentityId}`
   */
  getBrandIdentity(params: GetBrandIdentityParams, options?: RequestOptions): Promise<GetBrandIdentityResult> {
    return this.#transport.call(OPERATIONS.getBrandIdentity, params, options) as Promise<GetBrandIdentityResult>;
  }

  /**
   * Update a single brand identity
   *
   * Updates brand identity fields. Pass isDefault: true to make the target brand identity the organization's default.
   *
   * `PATCH /v1/brand-identities/{brandIdentityId}`
   */
  updateBrandIdentity(params: UpdateBrandIdentityParams, options?: RequestOptions): Promise<UpdateBrandIdentityResult> {
    return this.#transport.call(OPERATIONS.updateBrandIdentity, params, options) as Promise<UpdateBrandIdentityResult>;
  }

  /**
   * Delete a single brand identity
   *
   * Deletes a non-default brand identity and disables any automation triggers that reference it.
   *
   * `DELETE /v1/brand-identities/{brandIdentityId}`
   */
  deleteBrandIdentity(params: DeleteBrandIdentityParams, options?: RequestOptions): Promise<DeleteBrandIdentityResult> {
    return this.#transport.call(OPERATIONS.deleteBrandIdentity, params, options) as Promise<DeleteBrandIdentityResult>;
  }

  /**
   * List brand colors
   *
   * Returns the brand guideline colors of a brand identity.
   *
   * `GET /v1/brand-identities/{brandIdentityId}/colors`
   */
  listBrandColors(params: ListBrandColorsParams, options?: RequestOptions): Promise<ListBrandColorsResult> {
    return this.#transport.call(OPERATIONS.listBrandColors, params, options) as Promise<ListBrandColorsResult>;
  }

  /**
   * Add a brand color
   *
   * Adds a color to the brand guidelines of a brand identity.
   *
   * `POST /v1/brand-identities/{brandIdentityId}/colors`
   */
  createBrandColor(params: CreateBrandColorParams, options?: RequestOptions): Promise<CreateBrandColorResult> {
    return this.#transport.call(OPERATIONS.createBrandColor, params, options) as Promise<CreateBrandColorResult>;
  }

  /**
   * Update a brand color
   *
   * Updates the given fields of a brand color.
   *
   * `PATCH /v1/brand-identities/{brandIdentityId}/colors/{colorId}`
   */
  updateBrandColor(params: UpdateBrandColorParams, options?: RequestOptions): Promise<UpdateBrandColorResult> {
    return this.#transport.call(OPERATIONS.updateBrandColor, params, options) as Promise<UpdateBrandColorResult>;
  }

  /**
   * Delete a brand color
   *
   * Removes a color from the brand guidelines.
   *
   * `DELETE /v1/brand-identities/{brandIdentityId}/colors/{colorId}`
   */
  deleteBrandColor(params: DeleteBrandColorParams, options?: RequestOptions): Promise<DeleteBrandColorResult> {
    return this.#transport.call(OPERATIONS.deleteBrandColor, params, options) as Promise<DeleteBrandColorResult>;
  }

  /**
   * List available integrations
   *
   * Returns the enabled GitHub and Linear integrations for the organization. The slack array is always empty.
   *
   * `GET /v1/integrations`
   */
  listIntegrations(options?: RequestOptions): Promise<ListIntegrationsResult> {
    return this.#transport.call(OPERATIONS.listIntegrations, undefined, options) as Promise<ListIntegrationsResult>;
  }

  /**
   * Create a GitHub integration
   *
   * Checks that the repository can be read (a personal access token is required for private repositories), connects it, and enables changelog generation for it; blog post and X post outputs start disabled. A webhook secret is generated on creation. Copy the payload URL and secret from the dashboard to receive push and release events.
   *
   * `POST /v1/integrations/github`
   */
  createGitHubIntegration(params: CreateGitHubIntegrationParams, options?: RequestOptions): Promise<CreateGitHubIntegrationResult> {
    return this.#transport.call(OPERATIONS.createGitHubIntegration, params, options) as Promise<CreateGitHubIntegrationResult>;
  }

  /**
   * List recent GitHub activity
   *
   * Lists pull requests merged into the default branch, commits on the default branch, or releases published in a connected repository within a time window, so you can decide what to write about before calling create_post or generate_post. Reads GitHub live; pagination follows GitHub's pages, so a page can hold fewer items than the page size while nextPage is still set.
   *
   * `GET /v1/integrations/github/{integrationId}/activity`
   */
  getGitHubActivity(params: GetGitHubActivityParams, options?: RequestOptions): Promise<GetGitHubActivityResult> {
    return this.#transport.call(OPERATIONS.getGitHubActivity, params, options) as Promise<GetGitHubActivityResult>;
  }

  /**
   * Delete a single integration
   *
   * Deletes a GitHub or Linear integration. Schedules and event triggers that target the integration are disabled and listed in the response.
   *
   * `DELETE /v1/integrations/{integrationId}`
   */
  deleteIntegration(params: DeleteIntegrationParams, options?: RequestOptions): Promise<DeleteIntegrationResult> {
    return this.#transport.call(OPERATIONS.deleteIntegration, params, options) as Promise<DeleteIntegrationResult>;
  }
}

