/**
 * The Schedules endpoints, as `notra.schedules`.
 */
export class SchedulesResource {
  readonly #transport: Transport;

  constructor(transport: Transport) {
    this.#transport = transport;
  }

  /**
   * List schedules
   *
   * Returns the organization's cron schedules, newest first. repositoryMap maps each targeted GitHub integration ID to an owner/repo label.
   *
   * `GET /v1/schedules`
   */
  listSchedules(params?: ListSchedulesParams, options?: RequestOptions): Promise<ListSchedulesResult> {
    return this.#transport.call(OPERATIONS.listSchedules, params, options) as Promise<ListSchedulesResult>;
  }

  /**
   * Create a schedule
   *
   * Creates a recurring schedule that generates one content type from the selected GitHub and Linear integrations. Set at least one in targets.repositoryIds or targets.linearIntegrationIds. Times are in UTC. A schedule with the same source, targets, output, and lookback settings as an existing one is rejected with 409.
   *
   * `POST /v1/schedules`
   */
  createSchedule(params: CreateScheduleParams, options?: RequestOptions): Promise<CreateScheduleResult> {
    return this.#transport.call(OPERATIONS.createSchedule, params, options) as Promise<CreateScheduleResult>;
  }

  /**
   * Update a schedule
   *
   * Updates only the fields you send; everything else keeps its current value. targets and outputConfig merge field by field, sourceConfig.cron is replaced as a whole, and null clears an outputConfig field. The updated schedule is validated like a new one, so it must keep at least one GitHub or Linear integration.
   *
   * `PATCH /v1/schedules/{scheduleId}`
   */
  updateSchedule(params: UpdateScheduleParams, options?: RequestOptions): Promise<UpdateScheduleResult> {
    return this.#transport.call(OPERATIONS.updateSchedule, params, options) as Promise<UpdateScheduleResult>;
  }

  /**
   * Delete a schedule
   *
   * Deletes the schedule and stops future runs. Posts generated by earlier runs are kept.
   *
   * `DELETE /v1/schedules/{scheduleId}`
   */
  deleteSchedule(params: DeleteScheduleParams, options?: RequestOptions): Promise<DeleteScheduleResult> {
    return this.#transport.call(OPERATIONS.deleteSchedule, params, options) as Promise<DeleteScheduleResult>;
  }

  /**
   * Run a schedule now
   *
   * Starts one run of an enabled schedule right away, outside its cron timing, as the dashboard's Run now does. Returns 202 with the run's ID; follow it with `GET /v1/schedules/{scheduleId}/runs` until its status leaves `running`. Disabled schedules return 400.
   *
   * `POST /v1/schedules/{scheduleId}/run`
   */
  runSchedule(params: RunScheduleParams, options?: RequestOptions): Promise<RunScheduleResult> {
    return this.#transport.call(OPERATIONS.runSchedule, params, options) as Promise<RunScheduleResult>;
  }

  /**
   * List a schedule's runs
   *
   * Returns the schedule's most recent runs, newest first, with their status and the draft post each run created.
   *
   * `GET /v1/schedules/{scheduleId}/runs`
   */
  listScheduleRuns(params: ListScheduleRunsParams, options?: RequestOptions): Promise<ListScheduleRunsResult> {
    return this.#transport.call(OPERATIONS.listScheduleRuns, params, options) as Promise<ListScheduleRunsResult>;
  }
}

