/**
 * The Sites endpoints, as `notra.sites`.
 */
export class SitesResource {
  readonly #transport: Transport;

  constructor(transport: Transport) {
    this.#transport = transport;
  }

  /**
   * List Notra Sites
   *
   * Returns the organization's Notra Sites, oldest first. Sites with a blogMount have authors.
   *
   * `GET /v1/sites`
   */
  listSites(options?: RequestOptions): Promise<ListSitesResult> {
    return this.#transport.call(OPERATIONS.listSites, undefined, options) as Promise<ListSitesResult>;
  }

  /**
   * List a site's authors
   *
   * Returns the authors in the site's blog.json, including unpublished Design changes, with how many Notra posts credit each one, plus the author page layout.
   *
   * `GET /v1/sites/{siteId}/authors`
   */
  listSiteAuthors(params: ListSiteAuthorsParams, options?: RequestOptions): Promise<ListSiteAuthorsResult> {
    return this.#transport.call(OPERATIONS.listSiteAuthors, params, options) as Promise<ListSiteAuthorsResult>;
  }

  /**
   * Create or update a site author
   *
   * Creates the author or replaces all of its fields. Send previousId to rename an author; renaming one that is live or credited on Notra posts needs force: true, since those posts lose the link. Changes are saved as unpublished Design changes to the site's blog.json, the same draft the dashboard's Design tab shows, and go live when published with POST /v1/sites/{siteId}/publish or from the dashboard.
   *
   * `PUT /v1/sites/{siteId}/authors/{authorId}`
   */
  upsertSiteAuthor(params: UpsertSiteAuthorParams, options?: RequestOptions): Promise<UpsertSiteAuthorResult> {
    return this.#transport.call(OPERATIONS.upsertSiteAuthor, params, options) as Promise<UpsertSiteAuthorResult>;
  }

  /**
   * Delete a site author
   *
   * Removes the author from blog.json. Deleting one that is live or credited on Notra posts needs force=true; those posts then show the id as a plain name. Changes are saved as unpublished Design changes to the site's blog.json, the same draft the dashboard's Design tab shows, and go live when published with POST /v1/sites/{siteId}/publish or from the dashboard.
   *
   * `DELETE /v1/sites/{siteId}/authors/{authorId}`
   */
  deleteSiteAuthor(params: DeleteSiteAuthorParams, options?: RequestOptions): Promise<DeleteSiteAuthorResult> {
    return this.#transport.call(OPERATIONS.deleteSiteAuthor, params, options) as Promise<DeleteSiteAuthorResult>;
  }

  /**
   * Import Notra authors into a site
   *
   * Copies Notra authors (GET /v1/posts/authors) into blog.json, using their slug as the id. Avatars on https URLs are kept; dashboard uploads are listed in avatarsSkipped. Changes are saved as unpublished Design changes to the site's blog.json, the same draft the dashboard's Design tab shows, and go live when published with POST /v1/sites/{siteId}/publish or from the dashboard.
   *
   * `POST /v1/sites/{siteId}/authors/import`
   */
  importSiteAuthors(params: ImportSiteAuthorsParams, options?: RequestOptions): Promise<ImportSiteAuthorsResult> {
    return this.#transport.call(OPERATIONS.importSiteAuthors, params, options) as Promise<ImportSiteAuthorsResult>;
  }

  /**
   * Set the author page layout
   *
   * Sets blog.authorPage, the layout of every author page. Changes are saved as unpublished Design changes to the site's blog.json, the same draft the dashboard's Design tab shows, and go live when published with POST /v1/sites/{siteId}/publish or from the dashboard.
   *
   * `PATCH /v1/sites/{siteId}/author-page`
   */
  updateSiteAuthorPage(params: UpdateSiteAuthorPageParams, options?: RequestOptions): Promise<UpdateSiteAuthorPageResult> {
    return this.#transport.call(OPERATIONS.updateSiteAuthorPage, params, options) as Promise<UpdateSiteAuthorPageResult>;
  }

  /**
   * Set the blog and changelog paths
   *
   * Sets sections in blog.json: which of the blog and changelog the Site serves, and at which paths. A section left out is turned off. Once a production build with them goes live, they replace the dashboard's Sections setting, and a section that moves or turns off stops answering at its old path, so add redirects for it. Changes are saved as unpublished Design changes to the site's blog.json, the same draft the dashboard's Design tab shows, and go live when published with POST /v1/sites/{siteId}/publish or from the dashboard.
   *
   * `PATCH /v1/sites/{siteId}/sections`
   */
  updateSiteSections(params: UpdateSiteSectionsParams, options?: RequestOptions): Promise<UpdateSiteSectionsResult> {
    return this.#transport.call(OPERATIONS.updateSiteSections, params, options) as Promise<UpdateSiteSectionsResult>;
  }

  /**
   * Publish a site's Design changes
   *
   * Commits the unpublished blog.json changes, with the images they use, to the site's production branch and deploys it, like Publish in the dashboard. Returns 409 with code SITE_HAS_OTHER_CHANGES when other files have unpublished changes, so work staged in the dashboard is never published by accident; publish those from the dashboard.
   *
   * `POST /v1/sites/{siteId}/publish`
   */
  publishSite(params: PublishSiteParams, options?: RequestOptions): Promise<PublishSiteResult> {
    return this.#transport.call(OPERATIONS.publishSite, params, options) as Promise<PublishSiteResult>;
  }

  /**
   * Get a Site
   *
   * Returns a Site's settings, live deployment, custom domains with their DNS records, and open previews.
   *
   * `GET /v1/sites/{siteId}`
   */
  getSite(params: GetSiteParams, options?: RequestOptions): Promise<GetSiteResult> {
    return this.#transport.call(OPERATIONS.getSite, params, options) as Promise<GetSiteResult>;
  }

  /**
   * List a Site's deployments
   *
   * Lists production and preview builds, newest first, with their status, commit and compiler diagnostics. Live deployments are always included.
   *
   * `GET /v1/sites/{siteId}/deployments`
   */
  listSiteDeployments(params: ListSiteDeploymentsParams, options?: RequestOptions): Promise<ListSiteDeploymentsResult> {
    return this.#transport.call(OPERATIONS.listSiteDeployments, params, options) as Promise<ListSiteDeploymentsResult>;
  }

  /**
   * Deploy the production branch
   *
   * Queues a production build of the newest commit on the Site's production branch. Poll GET /v1/sites/{siteId}/deployments/{deploymentId} until the status is final.
   *
   * `POST /v1/sites/{siteId}/deployments`
   */
  startSiteDeployment(params: StartSiteDeploymentParams, options?: RequestOptions): Promise<StartSiteDeploymentResult> {
    return this.#transport.call(OPERATIONS.startSiteDeployment, params, options) as Promise<StartSiteDeploymentResult>;
  }

  /**
   * Get a deployment and its build log
   *
   * Returns one deployment with its compiler diagnostics and the newest build log output. Use it to follow a build or find out why one failed.
   *
   * `GET /v1/sites/{siteId}/deployments/{deploymentId}`
   */
  getSiteDeployment(params: GetSiteDeploymentParams, options?: RequestOptions): Promise<GetSiteDeploymentResult> {
    return this.#transport.call(OPERATIONS.getSiteDeployment, params, options) as Promise<GetSiteDeploymentResult>;
  }

  /**
   * Rebuild a deployment
   *
   * Queues a new build of the same commit, for example to retry a failed build. Rebuilding a production deployment older than the live one is a rollback and is refused; roll back in the dashboard.
   *
   * `POST /v1/sites/{siteId}/deployments/{deploymentId}/redeploy`
   */
  redeploySiteDeployment(params: RedeploySiteDeploymentParams, options?: RequestOptions): Promise<RedeploySiteDeploymentResult> {
    return this.#transport.call(OPERATIONS.redeploySiteDeployment, params, options) as Promise<RedeploySiteDeploymentResult>;
  }

  /**
   * Preview a post on a Site
   *
   * Builds a preview of the Site with the post added, without writing to the repository, and returns its URL. Workspace members open protected previews after signing in; set a password to share it with others. Starts a site build; poll GET /v1/sites/{siteId}/post-previews/{postId} until it is live.
   *
   * `POST /v1/sites/{siteId}/post-previews`
   */
  createSitePostPreview(params: CreateSitePostPreviewParams, options?: RequestOptions): Promise<CreateSitePostPreviewResult> {
    return this.#transport.call(OPERATIONS.createSitePostPreview, params, options) as Promise<CreateSitePostPreviewResult>;
  }

  /**
   * Get a post preview
   *
   * Returns the status and URL of a post's preview on a Site.
   *
   * `GET /v1/sites/{siteId}/post-previews/{postId}`
   */
  getSitePostPreview(params: GetSitePostPreviewParams, options?: RequestOptions): Promise<GetSitePostPreviewResult> {
    return this.#transport.call(OPERATIONS.getSitePostPreview, params, options) as Promise<GetSitePostPreviewResult>;
  }

  /**
   * Publish a post to a Site
   *
   * Opens a pull request that adds a blog post or changelog to the Site's repository, with its images and frontmatter, or updates the post's open pull request. The Site goes live with the post once the pull request is merged, even when the repository publishes directly from the dashboard.
   *
   * `POST /v1/sites/{siteId}/publications`
   */
  publishPostToSite(params: PublishPostToSiteParams, options?: RequestOptions): Promise<PublishPostToSiteResult> {
    return this.#transport.call(OPERATIONS.publishPostToSite, params, options) as Promise<PublishPostToSiteResult>;
  }
}

